// this file is generated by ai
import React, { useState, useEffect, useRef } from 'react';
import DeckGL from '@deck.gl/react';
import { ScatterplotLayer, PathLayer, LineLayer, TextLayer, IconLayer, BitmapLayer } from '@deck.gl/layers';
import { TileLayer } from '@deck.gl/geo-layers';

const WS_URL = 'ws://localhost:8080';

// Reference antenna origin loaded from the root .env file
const ANTENNA_ORIGIN = {
  longitude: Number(import.meta.env.REF_LON) || 0.0,
  latitude: Number(import.meta.env.REF_LAT) || 0.0,
  altitude: Number(import.meta.env.REF_ALT_M) || 0.0
};

const INITIAL_VIEW_STATE = {
  longitude: ANTENNA_ORIGIN.longitude,
  latitude: ANTENNA_ORIGIN.latitude,
  zoom: 10,
  pitch: 50,
  bearing: 0
};

// Crisp top-down commercial jet SVG encoded as a Data URL (mask: true allows dynamic RGBA tinting!)
const AIRPLANE_SVG = `data:image/svg+xml;utf8,${encodeURIComponent(
  '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="64" height="64" fill="white">' +
  '<path d="M21 16v-2l-8-5V3.5c0-.83-.67-1.5-1.5-1.5S10 2.67 10 3.5V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5l8 2.5z"/>' +
  '</svg>'
)}`;

const ICON_MAPPING = {
  airplane: { x: 0, y: 0, width: 64, height: 64, anchorY: 32, mask: true }
};

// Compute compass rotation angle for Deck.gl IconLayer from Kalman ENU velocities (vx, vy)
function getHeadingAngle(d) {
  if (typeof d.vx !== 'number' || typeof d.vy !== 'number') return 0;
  if (Math.abs(d.vx) < 0.1 && Math.abs(d.vy) < 0.1) return 0;
  // atan2(vx, vy) gives CW angle from North; negate for Deck.gl CCW screen rotation
  return -(Math.atan2(d.vx, d.vy) * 180) / Math.PI;
}

const renderBitmapTile = props => {
  const { boundingBox } = props.tile;
  return new BitmapLayer(props, {
    data: null,
    image: props.data,
    bounds: [boundingBox[0][0], boundingBox[0][1], boundingBox[1][0], boundingBox[1][1]]
  });
};

export default function App() {
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [aircraftList, setAircraftList] = useState([]);
  const [wsConnected, setWsConnected] = useState(false);

  // Spoofing UI controls
  const [activeSpoofTarget, setActiveSpoofTarget] = useState('NONE');
  const [customHexInput, setCustomHexInput] = useState('');

  const aircraftMapRef = useRef(new Map());
  const wsRef = useRef(null);

  // Send a spoofing target command to bridge/server.js
  const sendSpoofCommand = (targetValue) => {
    if (wsRef.current && wsRef.current.readyState === 1) {
      wsRef.current.send(JSON.stringify({
        type: 'SET_SPOOF',
        target: targetValue
      }));
    }
  };

  useEffect(() => {
    let ws;
    let reconnectTimer;

    function connect() {
      ws = new WebSocket(WS_URL);
      wsRef.current = ws;

      ws.onopen = () => {
        setWsConnected(true);
      };

      ws.onmessage = (event) => {
        try {
          const msg = JSON.parse(event.data);

          // Check if this message is a spoof configuration update from server.js
          if (msg.type === 'SPOOF_CONFIG') {
            setActiveSpoofTarget(msg.target);
            return;
          }

          // Otherwise it is an aircraft Kalman telemetry packet
          const ping = msg;
          const map = aircraftMapRef.current;
          const prev = map.get(ping.hex);

          const filtCoord = [ping.filtered_lon, ping.filtered_lat, ping.filtered_alt_m];
          const rawCoord = [ping.raw_lon, ping.raw_lat, ping.raw_alt_m];

          const filteredPath = prev ? [...prev.filteredPath.slice(-200), filtCoord] : [filtCoord];
          const rawPath = prev ? [...prev.rawPath.slice(-200), rawCoord] : [rawCoord];

          map.set(ping.hex, {
            ...ping,
            lastSeenMs: Date.now(),
            filteredPath,
            rawPath
          });
        } catch (err) {
          console.error('Failed to parse WS message:', err);
        }
      };

      ws.onclose = () => {
        setWsConnected(false);
        reconnectTimer = setTimeout(connect, 2000);
      };
    }

    connect();

    const uiInterval = setInterval(() => {
      const now = Date.now();
      const map = aircraftMapRef.current;
      for (const [hex, ac] of map.entries()) {
        if (now - ac.lastSeenMs > 60000) {
          map.delete(hex);
        }
      }
      setAircraftList(Array.from(map.values()));
    }, 66);

    return () => {
      clearInterval(uiInterval);
      clearTimeout(reconnectTimer);
      if (ws) ws.close();
    };
  }, []);

  const anomalousAircraft = aircraftList.filter(d => d.is_anomalous);

  const layers = [
    // 1A. Base Map Layer
    new TileLayer({
      id: isDarkMode ? 'dark-base-map' : 'light-base-map',
      data: isDarkMode
        ? 'https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Base/MapServer/tile/{z}/{y}/{x}'
        : 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
      minZoom: 0,
      maxZoom: isDarkMode ? 16 : 19,
      tileSize: 256,
      renderSubLayers: renderBitmapTile
    }),

    // 1B. Dark Labels Overlay
    isDarkMode && new TileLayer({
      id: 'dark-base-labels',
      data: 'https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Reference/MapServer/tile/{z}/{y}/{x}',
      minZoom: 0,
      maxZoom: 16,
      tileSize: 256,
      renderSubLayers: renderBitmapTile
    }),

    // 2. Reference Antenna Origin Marker
    new ScatterplotLayer({
      id: 'antenna-origin-layer',
      data: [ANTENNA_ORIGIN],
      getPosition: d => [d.longitude, d.latitude, d.altitude],
      getFillColor: [0, 220, 255, 220],
      getRadius: 250,
      radiusMinPixels: 5
    }),

    // 3. Kalman Uncertainty Radius Halo
    new ScatterplotLayer({
      id: 'uncertainty-halo-layer',
      data: aircraftList,
      getPosition: d => [d.filtered_lon, d.filtered_lat, d.filtered_alt_m],
      getRadius: d => d.uncertainty_m,
      getFillColor: d => d.is_anomalous ? [255, 165, 0, 50] : [0, 255, 170, 35],
      getLineColor: d => d.is_anomalous ? [255, 165, 0, 180] : [0, 255, 170, 120],
      stroked: true,
      lineWidthMinPixels: 1
    }),

    // 4. Kalman Filtered 3D Flight Path
    new PathLayer({
      id: 'filtered-trajectory-layer',
      data: aircraftList,
      getPath: d => d.filteredPath,
      getColor: d => d.is_anomalous ? [255, 200, 0, 230] : [0, 255, 170, 210],
      getWidth: 4,
      widthMinPixels: 2
    }),

    // 5. Spoofing Displacement Vector (Line from Filtered Pos -> Rejected Spoof Pos)
    new LineLayer({
      id: 'spoof-vector-layer',
      data: anomalousAircraft,
      getSourcePosition: d => [d.filtered_lon, d.filtered_lat, d.filtered_alt_m],
      getTargetPosition: d => [d.raw_lon, d.raw_lat, d.raw_alt_m],
      getColor: [255, 40, 60, 230],
      getWidth: 3,
      widthMinPixels: 2
    }),

    // 6. Rejected Raw Spoofed Phantom Aircraft Icon (Red)
    new IconLayer({
      id: 'raw-spoof-aircraft-icon',
      data: anomalousAircraft,
      iconAtlas: AIRPLANE_SVG,
      iconMapping: ICON_MAPPING,
      getIcon: () => 'airplane',
      sizeScale: 1,
      getPosition: d => [d.raw_lon, d.raw_lat, d.raw_alt_m],
      getSize: 24,
      getAngle: d => getHeadingAngle(d),
      getColor: [255, 30, 50, 230],
      billboard: false
    }),

    // 7. Kalman Filtered Real Aircraft Icon (Green when normal, Amber when coasting, Clickable to Spoof!)
    new IconLayer({
      id: 'filtered-aircraft-icon',
      data: aircraftList,
      iconAtlas: AIRPLANE_SVG,
      iconMapping: ICON_MAPPING,
      getIcon: () => 'airplane',
      sizeScale: 1,
      getPosition: d => [d.filtered_lon, d.filtered_lat, d.filtered_alt_m],
      getSize: 28,
      getAngle: d => getHeadingAngle(d),
      getColor: d => d.is_anomalous ? [255, 180, 0, 255] : [0, 255, 170, 255],
      billboard: false,
      pickable: true,
      onClick: ({ object }) => {
        if (object && object.hex) {
          setCustomHexInput(object.hex);
        }
      }
    }),

    // 8. Aircraft Callsign & Spoof Alert Labels
    new TextLayer({
      id: 'aircraft-labels',
      data: aircraftList,
      getPosition: d => [d.filtered_lon, d.filtered_lat, d.filtered_alt_m + 150],
      getText: d => {
        const name = d.callsign && d.callsign !== 'N/A' ? d.callsign.trim() : d.hex;
        return d.is_anomalous ? `⚠️ ${name} [SPOOF REJECTED]` : name;
      },
      getSize: 13,
      getColor: d => d.is_anomalous ? [255, 80, 80, 255] : (isDarkMode ? [230, 240, 255, 230] : [15, 23, 42, 240]),
      getTextAnchor: 'middle',
      getAlignmentBaseline: 'bottom'
    })
  ];

  const panelBg = isDarkMode ? 'rgba(15, 23, 42, 0.90)' : 'rgba(255, 255, 255, 0.94)';
  const panelText = isDarkMode ? '#f8fafc' : '#0f172a';
  const panelBorder = isDarkMode ? '1px solid #334155' : '1px solid #cbd5e1';

  return (
    <div style={{
      width: '100vw',
      height: '100vh',
      position: 'relative',
      overflow: 'hidden',
      background: isDarkMode ? '#0b0f19' : '#e5e3df',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <DeckGL
        initialViewState={INITIAL_VIEW_STATE}
        controller={true}
        layers={layers}
        getTooltip={({ object }) => object && object.hex && (
          `ICAO: ${object.hex} (${object.callsign})\n` +
          `Alt: ${Math.round(object.filtered_alt_m)}m\n` +
          `Uncertainty: ±${object.uncertainty_m.toFixed(1)}m\n` +
          `Mahalanobis d²: ${object.mahalanobis_d2.toFixed(1)}\n` +
          `Status: ${object.is_anomalous ? '🚨 ' + object.anomaly_reason : '✅ NORMAL'}\n` +
          `(Click plane to copy ICAO hex to Spoof Control)`
        )}
      />

      {/* Top-Left Telemetry & Red-Team Spoof Injector Panel */}
      <div style={{
        position: 'absolute',
        top: '20px',
        left: '20px',
        zIndex: 10,
        padding: '16px 18px',
        borderRadius: '12px',
        background: panelBg,
        color: panelText,
        border: panelBorder,
        boxShadow: '0 4px 16px rgba(0,0,0,0.35)',
        width: '290px'
      }}>
        <div style={{ fontWeight: 'bold', fontSize: '16px', marginBottom: '8px' }}>
          🛡️ ADS-B Kalman Guard
        </div>
        <div style={{ fontSize: '13px', marginBottom: '4px' }}>
          Bridge: <span style={{ color: wsConnected ? '#10b981' : '#ef4444', fontWeight: 'bold' }}>
            {wsConnected ? '● LIVE' : '○ DISCONNECTED'}
          </span>
        </div>
        <div style={{ fontSize: '13px', marginBottom: '4px' }}>
          Tracked Aircraft: <b>{aircraftList.length}</b>
        </div>
        <div style={{
          fontSize: '13px',
          marginBottom: '12px',
          color: anomalousAircraft.length > 0 ? '#ef4444' : 'inherit',
          fontWeight: anomalousAircraft.length > 0 ? 'bold' : 'normal'
        }}>
          Active Spoof Alerts: {anomalousAircraft.length}
        </div>

        <hr style={{ border: 'none', borderTop: panelBorder, margin: '10px 0' }} />

        {/* Red-Team Spoofing Control Section */}
        <div style={{ fontWeight: 'bold', fontSize: '13px', marginBottom: '6px' }}>
          🎯 Red-Team Spoof Injector
        </div>
        <div style={{ fontSize: '12px', marginBottom: '10px', opacity: 0.85 }}>
          Active Target: <b style={{ color: activeSpoofTarget !== 'NONE' ? '#f59e0b' : '#10b981' }}>
            {activeSpoofTarget}
          </b>
        </div>

        {/* Quick Action Buttons: Spoof All vs Disable */}
        <div style={{ display: 'flex', gap: '8px', marginBottom: '10px' }}>
          <button
            onClick={() => sendSpoofCommand('ANY')}
            style={{
              flex: 1,
              padding: '7px 10px',
              borderRadius: '6px',
              border: 'none',
              background: activeSpoofTarget === 'ANY' ? '#dc2626' : '#ef4444',
              color: '#fff',
              fontWeight: 'bold',
              fontSize: '12px',
              cursor: 'pointer'
            }}
          >
            🚨 Spoof ALL
          </button>
          <button
            onClick={() => sendSpoofCommand('NONE')}
            style={{
              flex: 1,
              padding: '7px 10px',
              borderRadius: '6px',
              border: 'none',
              background: '#10b981',
              color: '#fff',
              fontWeight: 'bold',
              fontSize: '12px',
              cursor: 'pointer'
            }}
          >
            ✅ Stop Spoof
          </button>
        </div>

        {/* Specific Aircraft ICAO Hex Input + Dropdown */}
        <div style={{ fontSize: '12px', marginBottom: '4px', opacity: 0.85 }}>
          Or target specific ICAO Hex (click plane or select):
        </div>
        <div style={{ display: 'flex', gap: '6px', marginBottom: '6px' }}>
          <input
            type="text"
            placeholder="e.g. 407fc2"
            value={customHexInput}
            onChange={e => setCustomHexInput(e.target.value)}
            style={{
              flex: 1,
              padding: '6px 8px',
              borderRadius: '6px',
              border: panelBorder,
              background: isDarkMode ? '#1e293b' : '#f1f5f9',
              color: panelText,
              fontSize: '12px'
            }}
          />
          <button
            onClick={() => customHexInput.trim() && sendSpoofCommand(customHexInput.trim())}
            style={{
              padding: '6px 12px',
              borderRadius: '6px',
              border: 'none',
              background: '#f59e0b',
              color: '#0f172a',
              fontWeight: 'bold',
              fontSize: '12px',
              cursor: 'pointer'
            }}
          >
            Spoof Hex
          </button>
        </div>

        {/* Live Aircraft Quick-Select Dropdown */}
        {aircraftList.length > 0 && (
          <select
            value=""
            onChange={(e) => {
              if (e.target.value) {
                setCustomHexInput(e.target.value);
                sendSpoofCommand(e.target.value);
              }
            }}
            style={{
              width: '100%',
              padding: '6px 8px',
              borderRadius: '6px',
              border: panelBorder,
              background: isDarkMode ? '#1e293b' : '#f1f5f9',
              color: panelText,
              fontSize: '12px',
              cursor: 'pointer'
            }}
          >
            <option value="">-- Quick-select tracked aircraft --</option>
            {aircraftList.map(ac => (
              <option key={ac.hex} value={ac.hex}>
                {ac.hex} ({ac.callsign && ac.callsign !== 'N/A' ? ac.callsign.trim() : 'No Callsign'})
              </option>
            ))}
          </select>
        )}
      </div>

      {/* Top-Right Theme Toggle Button */}
      <button
        onClick={() => setIsDarkMode(!isDarkMode)}
        style={{
          position: 'absolute',
          top: '20px',
          right: '20px',
          zIndex: 10,
          padding: '10px 16px',
          borderRadius: '8px',
          border: panelBorder,
          background: panelBg,
          color: panelText,
          fontWeight: 'bold',
          cursor: 'pointer',
          boxShadow: '0 4px 12px rgba(0,0,0,0.25)'
        }}
      >
        {isDarkMode ? '☀️ Light Mode' : '🌙 Dark Mode'}
      </button>
    </div>
  );
}